pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_fraction = step_index as f64 / total_jobs as f64;
    let dynamic_weight = 1.0 + step_fraction * 3.0; // Scale factor increases linearly with job index

    // Lookahead awareness (k=2)
    let next_cpu_norm = next_job_cpu as f64 / node_capacity_cpu as f64;
    let next_ram_norm = next_job_ram as f64 / node_capacity_ram as f64;
    let lookahead_penalty = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        0.0
    } else {
        (next_cpu_norm - next_ram_norm).abs() * dynamic_weight // Apply dynamic weight to lookahead penalty
    };

    // Non-linear conditionals and packing bonuses
    let cpu_packing_bonus = if job_cpu == node_residual_cpu { 1.5 } else { 1.0 };
    let ram_packing_bonus = if job_ram == node_residual_ram { 1.5 } else { 1.0 };
    let packing_bonus = cpu_packing_bonus * ram_packing_bonus;

    // Imbalance penalty modification
    let imbalance_factor = if imbalance_penalty > 0.1 { 2.0 } else { 1.0 }; // Penalize nodes with significant imbalances more heavily

    // Final score calculation
    let score = cpu_norm + ram_norm * imbalance_factor - lookahead_penalty * dynamic_weight + packing_bonus; // Adjust signs for optimization
    score
}

